-- MW Dynasty Founder OS v1
-- Applied to production 2026-09-20. Safe to re-run.

create table if not exists public.founder_ai_agents (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  name text not null,
  title text not null,
  department text not null,
  manager_code text,
  org_level text not null default 'specialist',
  mission text not null,
  responsibilities jsonb not null default '[]'::jsonb,
  kpis jsonb not null default '[]'::jsonb,
  authority_level text not null default 'analyze' check (authority_level in ('analyze','draft','execute_low_risk')),
  allowed_tools jsonb not null default '[]'::jsonb,
  status text not null default 'active' check (status in ('active','paused','retired')),
  sort_order integer not null default 100,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.founder_ai_tasks (
  id uuid primary key default gen_random_uuid(),
  agent_code text references public.founder_ai_agents(code) on update cascade,
  title text not null, description text, department text,
  priority text not null default 'normal' check (priority in ('low','normal','high','urgent')),
  status text not null default 'queued' check (status in ('queued','in_progress','waiting_approval','completed','blocked','cancelled')),
  source text not null default 'founder',
  requires_approval boolean not null default false,
  approval_status text check (approval_status is null or approval_status in ('pending','approved','rejected')),
  output_summary text, metadata jsonb not null default '{}'::jsonb,
  created_by uuid default auth.uid(), due_at timestamptz, completed_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.founder_approvals (
  id uuid primary key default gen_random_uuid(),
  category text not null, title text not null, description text,
  requested_action jsonb not null default '{}'::jsonb,
  risk_level text not null default 'medium' check (risk_level in ('low','medium','high','critical')),
  status text not null default 'pending' check (status in ('pending','approved','rejected','executed','cancelled')),
  requested_by_agent_code text references public.founder_ai_agents(code) on update cascade,
  reviewed_by uuid, review_note text, reviewed_at timestamptz, executed_at timestamptz,
  created_at timestamptz not null default now()
);
create table if not exists public.founder_knowledge_proposals (
  id uuid primary key default gen_random_uuid(),
  title text not null, principle_text text not null,
  structured_rule jsonb not null default '{}'::jsonb, affected_areas jsonb not null default '[]'::jsonb,
  conflict_notes text, status text not null default 'draft' check (status in ('draft','review','approved','rejected','published')),
  version integer not null default 1, created_by uuid default auth.uid(), reviewed_by uuid,
  reviewed_at timestamptz, published_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.founder_crm_leads (
  id uuid primary key default gen_random_uuid(),
  name text, organization text, contact_email text,
  lead_type text not null default 'coach' check (lead_type in ('coach','school','club','partner','other')),
  stage text not null default 'new' check (stage in ('new','qualified','contacted','meeting','proposal','negotiation','won','lost')),
  source text, assigned_agent_code text references public.founder_ai_agents(code) on update cascade,
  estimated_monthly_value_cents integer not null default 0 check (estimated_monthly_value_cents >= 0),
  next_action text, notes text, created_by uuid default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.founder_marketing_campaigns (
  id uuid primary key default gen_random_uuid(),
  name text not null, channel text not null,
  status text not null default 'draft' check (status in ('draft','scheduled','active','paused','completed','cancelled')),
  audience text, objective text, budget_cents integer not null default 0 check (budget_cents >= 0),
  spend_cents integer not null default 0 check (spend_cents >= 0),
  leads integer not null default 0 check (leads >= 0), conversions integer not null default 0 check (conversions >= 0),
  starts_at timestamptz, ends_at timestamptz, metadata jsonb not null default '{}'::jsonb,
  created_by uuid default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.founder_web_events (
  id bigint generated by default as identity primary key,
  session_key text not null, user_id uuid, event_type text not null, page_path text not null,
  audience text, source text, campaign text, referrer_host text, device_class text,
  metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()
);

create index if not exists founder_ai_tasks_status_idx on public.founder_ai_tasks(status,priority,created_at desc);
create index if not exists founder_approvals_status_idx on public.founder_approvals(status,risk_level,created_at desc);
create index if not exists founder_knowledge_status_idx on public.founder_knowledge_proposals(status,updated_at desc);
create index if not exists founder_crm_stage_idx on public.founder_crm_leads(stage,updated_at desc);
create index if not exists founder_campaign_status_idx on public.founder_marketing_campaigns(status,updated_at desc);
create index if not exists founder_web_events_created_idx on public.founder_web_events(created_at desc);
create index if not exists founder_web_events_session_idx on public.founder_web_events(session_key,created_at desc);
create index if not exists founder_web_events_type_idx on public.founder_web_events(event_type,created_at desc);

alter table public.founder_ai_agents enable row level security;
alter table public.founder_ai_tasks enable row level security;
alter table public.founder_approvals enable row level security;
alter table public.founder_knowledge_proposals enable row level security;
alter table public.founder_crm_leads enable row level security;
alter table public.founder_marketing_campaigns enable row level security;
alter table public.founder_web_events enable row level security;

do $$
declare t text;
begin
  foreach t in array array['founder_ai_agents','founder_ai_tasks','founder_approvals','founder_knowledge_proposals','founder_crm_leads','founder_marketing_campaigns','founder_web_events']
  loop
    execute format('drop policy if exists %I on public.%I','mw_founder_select_'||t,t);
    execute format('create policy %I on public.%I for select to authenticated using (private.mw_is_founder())','mw_founder_select_'||t,t);
  end loop;
end $$;
drop policy if exists mw_founder_modify_ai_tasks on public.founder_ai_tasks;
create policy mw_founder_modify_ai_tasks on public.founder_ai_tasks for all to authenticated using (private.mw_is_founder()) with check (private.mw_is_founder());
drop policy if exists mw_founder_modify_approvals on public.founder_approvals;
create policy mw_founder_modify_approvals on public.founder_approvals for all to authenticated using (private.mw_is_founder()) with check (private.mw_is_founder());
drop policy if exists mw_founder_modify_knowledge on public.founder_knowledge_proposals;
create policy mw_founder_modify_knowledge on public.founder_knowledge_proposals for all to authenticated using (private.mw_is_founder()) with check (private.mw_is_founder());
drop policy if exists mw_founder_modify_crm on public.founder_crm_leads;
create policy mw_founder_modify_crm on public.founder_crm_leads for all to authenticated using (private.mw_is_founder()) with check (private.mw_is_founder());
drop policy if exists mw_founder_modify_campaigns on public.founder_marketing_campaigns;
create policy mw_founder_modify_campaigns on public.founder_marketing_campaigns for all to authenticated using (private.mw_is_founder()) with check (private.mw_is_founder());


