uthority_level":"analyze","sort_order":100},{"code":"bi_analyst","name":"Business Intelligence AI","title":"Business Intelligence Analyst","department":"Data & Analytics","manager_code":"data_chief","org_level":"specialist","mission":"Build clear explanations of growth, revenue, retention, and usage.","responsibilities":["Dashboard analysis","Trend detection","Cohort reporting"],"kpis":["Insight quality","Report timeliness"],"authority_level":"analyze","sort_order":101},{"code":"legal_risk","name":"Legal & Risk AI","title":"Legal / Compliance / Risk Manager","department":"Legal / Compliance","manager_code":null,"org_level":"executive","mission":"Surface compliance, privacy, contract, and platform-risk issues for human review.","responsibilities":["Privacy review","Store policy review","Contract issue spotting","Risk register"],"kpis":["Open high-risk items","Policy readiness","Review turnaround"],"authority_level":"analyze","sort_order":110}]'::jsonb) as x(
